156	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
157	export function setupStroll(c: SwingController, onExit: () => void): void {
158	  ctrl = c; exit = onExit;
159	  window.addEventListener('keydown', (e) => {
160	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung); đang xem: không đọc phím
161	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
162	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
163	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
164	    const k = stKeyName(e);   // theo vị trí phím (e.code): bố cục không Latin (ru, ar, th, hi) vẫn dùng WASD
165	    if (k === 'p') { if (!e.repeat) stPhoto(); return; }   // P chụp ảnh, không ghi vào keys
166	    if (k === ' ') { e.preventDefault(); if (!e.repeat) jumpQueued = true; }
167	    else if (k.startsWith('arrow')) e.preventDefault();
168	    keys.add(k);
169	  });
170	  window.addEventListener('keyup', (e) => {
171	    const k = stKeyName(e);
172	    keys.delete(k); keys.delete(e.key.toLowerCase());   // cả tên cũ: phím dù lượn ghi theo e.key
173	    if (k === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
174	  });
175	  const drop = () => { keys.clear(); jumpQueued = false; };
176	  window.addEventListener('blur', drop);
177	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
178	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
179	  const hud = document.getElementById('stHud');
180	  if (hud) touch = stTouchBind(hud, {
181	    look: (dx, dy) => { if (active()) stCamDrag(camS, dx, dy, CONFIG.stroll.cam.touch); },
182	    jump: () => { if (active()) jumpQueued = true; },
183	    photo: stPhoto,
184	    activity: () => exMulti.activity()
185	  });
186	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
187	  let dragId = -1, lx = 0, ly = 0;
188	  canvas.addEventListener('pointerdown', (e) => {
189	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
190	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
191	    canvas.setPointerCapture(e.pointerId);
192	  });
193	  canvas.addEventListener('pointermove', (e) => {
194	    if (e.pointerId !== dragId) return;
195	    stCamDrag(camS, e.clientX - lx, e.clientY - ly, CONFIG.stroll.cam.mouse);
196	    exMulti.activity();   // xoay camera cũng tính là còn đó
197	    lx = e.clientX; ly = e.clientY;
198	  });
199	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
200	  canvas.addEventListener('pointerup', end);
201	  canvas.addEventListener('pointercancel', end);
202	  canvas.addEventListener('lostpointercapture', end);
203	}
