import fs from 'node:fs';
const dir = 'D:/2026 - Tuan/danang-vite/src/i18n/locales/';
for (const l of ['vi', 'en', 'ko', 'ja', 'zh', 'th', 'ar', 'hi', 'ru']) {
  const p = dir + l + '.json';
  let t = fs.readFileSync(p, 'utf8');
  const nl = t.includes('\r\n') ? '\r\n' : '\n';
  const lines = t.split(nl).filter((ln) => !/^\s*"stJump":/.test(ln));
  let n = 0;
  const out = lines.map((ln) => {
    if (!/^\s*"stHint":/.test(ln)) return ln;
    // bỏ đúng mục chứa "Space" (ngăn bằng " · ")
    const m = ln.match(/^(\s*"stHint": ")(.*)(".*)$/);
    const parts = m[2].split(' · ').filter((s) => !/^Space\s*[:：]/.test(s));
    n++;
    return m[1] + parts.join(' · ') + m[3];
  });
  if (n !== 1) throw new Error(l + ' stHint ' + n);
  const res = out.join(nl);
  JSON.parse(res);
  fs.writeFileSync(p, res);
  console.log(l, 'ok');
}

